/// <summary>
/// N.Freidenberger 12.08.24
/// </summary>
public void init()
{
    super();
    customersCopyToOrganizStructureHelper   = new AVACustomersCopyToOrganizStructureHelper();
}

/// <summary>
/// N.Freidenberger 03.09.2024
/// </summary>
public void closeOk()
{
    customersCopyToOrganizStructureHelper.setAVACustomersCopyToOrganizStructureTmp(AVACustomersCopyToOrganizStructureTmp);
    boolean ret = customersCopyToOrganizStructureHelper.checkCopyData();
    this.buildCustCompMap();
    ret = ret && this.checkParametersCrossCompany();
    ret = ret && this.checkNewCustAccountCrossCompany();
    if (ret)
    {
        super();
        customersCopyToOrganizStructureHelper.parmCustomerToOrgCompMap(custAccountCompaniesMap);
        customersCopyToOrganizStructureHelper.copyOriganizationStructure();
    }
    else
    {
        AVACustomersCopyToOrganizStructureTmp_ds.executeQuery();
    }
}

/// <summary>
/// N.Freidenberger 19.05.2025
/// </summary>
void buildCustCompMap()
{
    CustTable       crossCompCustTable;
    CustTable       locCustTable;
    Set             custAccountCompaniesSet;
    custAccountCompaniesMap = new Map(Types::String,Types::Class);
    companySetForCheckParameters = new Set(Types::String);

    while select AVACustomersCopyToOrganizStructureTmp
    {
        select firstonly Party from locCustTable
            where locCustTable.AccountNum == AVACustomersCopyToOrganizStructureTmp.CustAccountOld;

        custAccountCompaniesSet = new Set(Types::String);
        while select crosscompany     crossCompCustTable
            where crossCompCustTable.Party == locCustTable.Party
        {
            custAccountCompaniesSet.add(crossCompCustTable.DataAreaId);    
            companySetForCheckParameters.add(crossCompCustTable.DataAreaId);
        }
        custAccountCompaniesMap.insert(locCustTable.AccountNum,custAccountCompaniesSet);

    }
}

/// <summary>
/// N.Freidenberger 21.05.2025
/// </summary>
/// <returns>boolean</returns>
public boolean checkParametersCrossCompany()
{
    SetIterator   companySetForCheckIterator = new SetIterator(companySetForCheckParameters);
    boolean       ret = true;
    str           errorParam;
    Set           compToDelSet = new Set(Types::String);

    while (companySetForCheckIterator.more())
    {
        errorParam = '';
        changecompany(companySetForCheckIterator.value())
        {
            CustTable               invoiceCustTable;

            if (customersCopyToOrganizStructureHelper.parmInvoiceAccount() != '')
            {
                select firstonly AccountNum from invoiceCustTable
                where invoiceCustTable.AccountNum ==  customersCopyToOrganizStructureHelper.parmInvoiceAccount();

                if (!invoiceCustTable.AccountNum)
                {
                    errorParam = errorParam != '' ? errorParam + ', ' : errorParam;
                    errorParam += '@NDX:NXAInvoiceAccount';
                }
            }

            if (customersCopyToOrganizStructureHelper.parmTOSId() != '')
            {
                KCS_TOSTable       tosTable;

                select firstonly tosTable
                where tosTable.TosId == customersCopyToOrganizStructureHelper.parmTOSId();

                if (!tosTable.RecId)
                {
                    errorParam = errorParam != '' ? errorParam + ', ' : errorParam;
                    errorParam += '@TOS25';
                }
            }

            if (customersCopyToOrganizStructureHelper.parmCompanyChainId() != '')
            {
                smmBusRelChainGroup     smmBusRelChainGroup;

                select firstonly smmBusRelChainGroup
                where smmBusRelChainGroup.ChainId == customersCopyToOrganizStructureHelper.parmCompanyChainId();

                if(!smmBusRelChainGroup.ChainId)
                {
                    errorParam = errorParam != '' ? errorParam + ', ' : errorParam;
                    errorParam += '@SYS80316';
                }
            }

            if (customersCopyToOrganizStructureHelper.parmCustItemGroupId() != '')
            {
                CustVendItemGroup               custVendItemGroup;

                select firstonly custVendItemGroup
                where custVendItemGroup.GroupId == customersCopyToOrganizStructureHelper.parmCustItemGroupId();

                if (!custVendItemGroup)
                {
                    errorParam = errorParam != '' ? errorParam + ', ' : errorParam;
                    errorParam += '@SYS54800';
                }
            }

            if (errorParam != '')
            {
                if (Box::okCancel(strFmt('@NDX:NXAParamMissedInIC',companySetForCheckIterator.value(),errorParam),DialogButton::Cancel) == DialogButton::Cancel)
                {
                    ret = false;
                    break;
                }
                else
                {
                    compToDelSet.add(companySetForCheckIterator.value());
                }
            }
        }

        companySetForCheckIterator.next();
    }

    if (ret)
    {
        SetIterator   compToDelSetIterator = new SetIterator(compToDelSet);

        while (compToDelSetIterator.more())
        {
            companySetForCheckParameters.remove(compToDelSetIterator.value());
            compToDelSetIterator.next();
        }
    }

    return ret;
}

/// <summary>
/// N.Freidenberger 21.05.2025
/// </summary>
/// <returns>boolean</returns>
public boolean checkNewCustAccountCrossCompany()
{
    boolean  ret = true;
    MapIterator         custAccountCompaniesMapIterator = new MapIterator(custAccountCompaniesMap);
    AVACustomersCopyToOrganizStructureTmp   locAVACustomersCopyToOrganizStructureTmp;

    while (custAccountCompaniesMapIterator.more())
    {
        Set                     custAccountCompaniesSet = custAccountCompaniesMapIterator.value();
        SetIterator             custAccountCompaniesSetIterator = new SetIterator(custAccountCompaniesSet);
        Set                     companyToDelSet = new Set(Types::String);
        while (custAccountCompaniesSetIterator.value())
        {
            if (!companySetForCheckParameters.in(custAccountCompaniesSetIterator.value()))
            {
                companyToDelSet.add(custAccountCompaniesSetIterator.value());
            }
            else
            {
                changecompany(custAccountCompaniesSetIterator.value())
                {
                    CustTable       newCustTable;
                    select firstonly AVACustomersCopyToOrganizStructureTmp
                        where AVACustomersCopyToOrganizStructureTmp.CustAccountOld ==   custAccountCompaniesMapIterator.key();
                    select firstonly AccountNum from newCustTable
                        where newCustTable.AccountNum == AVACustomersCopyToOrganizStructureTmp.CustAccountNew;

                    if (newCustTable.AccountNum)
                    {
                        if (Box::okCancel(strFmt('@NDX:NXANewCustIsUsed',AVACustomersCopyToOrganizStructureTmp.CustAccountNew,custAccountCompaniesSetIterator.value()),DialogButton::Cancel) == DialogButton::Cancel)
                        {
                            ret = false;
                            break;
                        }
                        else
                        {
                            companyToDelSet.add(custAccountCompaniesSetIterator.value());
                        }
                    }

                }
            }
            if (!ret)
            {
                break;
            }
            custAccountCompaniesSetIterator.next();
        }

        if (!ret)
        {
            break;
        }
        else
        {
            SetIterator   compToDelSetIterator = new SetIterator(companyToDelSet);

            while (compToDelSetIterator.more())
            {
                custAccountCompaniesSet.remove(compToDelSetIterator.value());
                compToDelSetIterator.next();
            }
        }

        custAccountCompaniesMapIterator.next();
    }


    return ret;
}
